function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // ocean
  ctx.fillStyle = '#87ceeb';
  ctx.fillRect(0, H/2, W, H/2);

  // whale
  ctx.fillStyle = 'gray';
  ctx.beginPath();
  ctx.arc(W/2 + 100 * Math.sin(t), H - 100 - 50 * Math.sin(2*t), 50, 0, 2 * Math.PI);
  ctx.fill();
  ctx.stroke();

  // breach
  if (Math.sin(2*t) > 0.5) {
    ctx.fillStyle = 'white';
    ctx.beginPath();
    ctx.arc(W/2 + 100 * Math.sin(t), H - 100 - 50 * Math.sin(2*t), 20, 0, 2 * Math.PI);
    ctx.fill();
  }

  // stick figure diver
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 - 100, H/2 - 20 * Math.sin(t), 10, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 20 * Math.sin(t) + 10);
  ctx.lineTo(W/2 - 100, H/2 - 20 * Math.sin(t) + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 20 * Math.sin(t) + 30);
  ctx.lineTo(W/2 - 120, H/2 - 20 * Math.sin(t) + 50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2 - 100, H/2 - 20 * Math.sin(t) + 30);
  ctx.lineTo(W/2 - 80, H/2 - 20 * Math.sin(t) + 50);
  ctx.stroke();

  ctx.restore();
}
